export type Category =
  | "housing"
  | "food"
  | "mentalHealth"
  | "health"
  | "immigration"
  | "employment"
  | "family"
  | "social"
  | "childcare"
  | "realestate"
  | "administrative"
  | "legal";

export interface Coordinates {
  lat: number;
  lng: number;
}

export type ProvinceCode =
  | "QC"
  | "ON"
  | "BC"
  | "AB"
  | "MB"
  | "SK"
  | "NB"
  | "NS"
  | "PE"
  | "NL"
  | "YT"
  | "NT"
  | "NU";

